targets.query:
from(bucket: v.bucket)
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "netprobe_icmp" and r._field == "rtt_ms")
  |> filter(fn: (r) => r.target =~ /${target}/)
  |> aggregateWindow(
       every: v.windowPeriod,
       fn: (tables=<-, column) => quantile(tables: tables, q: 0.95, method: "estimate_tdigest", column: "_value"),
       createEmpty: false
     )
  |> yield(name: "p95")

